// ==== TarefaForm.js ====
// static/js/modules/pasta_tarefas/core/TarefaForm.js
// ==========================================================
// TarefaForm - Classe única para os modais Nova e Editar
// ==========================================================

(function() {
    'use strict';

    function TarefaForm(formEl, options) {
        if (!formEl) throw new Error('TarefaForm: formEl obrigatório');

        this.form = formEl;
        this.options = options || {};
        this.mode = this.options.mode || 'create';
        this.onSubmitSuccess = this.options.onSubmitSuccess || null;
        this.onSubmitError = this.options.onSubmitError || null;

        var modal = formEl.closest('.fin-modal-overlay') || formEl.closest('body');

        this.el = {
            titulo:      formEl.querySelector('.js-titulo'),
            descricao:   formEl.querySelector('.js-descricao'),
            status:      formEl.querySelector('.js-status'),
            prioridade:  formEl.querySelector('.js-prioridade'),
            dataInicio:  formEl.querySelector('.js-data-inicio'),
            dataFinal:   formEl.querySelector('.js-data-final'),
            categoria:   formEl.querySelector('.js-categoria'),
        };

        this._bind();
    }

    // ==========================================================
    // EVENTOS
    // ==========================================================
    TarefaForm.prototype._bind = function() {
        var self = this;

        // Auto-ajuste do textarea
        if (this.el.descricao) {
            var ajustar = function() {
                self.el.descricao.style.height = 'auto';
                self.el.descricao.style.height = (self.el.descricao.scrollHeight) + 'px';
            };
            this.el.descricao.addEventListener('input', ajustar);
            setTimeout(ajustar, 50);
        }
    };

    // ==========================================================
    // API PÚBLICA: setData (usado no modo edit)
    // ==========================================================
    TarefaForm.prototype.setData = function(data) {
        if (!data) return;

        if (this.el.titulo)     this.el.titulo.value     = data.titulo || '';
        if (this.el.descricao)  this.el.descricao.value  = data.descricao || '';
        if (this.el.status)     this.el.status.value     = data.status || 'pendente';
        if (this.el.prioridade) this.el.prioridade.value = data.prioridade || 'media';
        if (this.el.dataInicio) this.el.dataInicio.value = data.data_inicio || '';
        if (this.el.dataFinal)  this.el.dataFinal.value  = data.data_final || '';
        if (this.el.categoria)  this.el.categoria.value  = data.categoria_id || '';

        // Atualiza altura do textarea depois de setar valor
        if (this.el.descricao) {
            this.el.descricao.style.height = 'auto';
            this.el.descricao.style.height = (this.el.descricao.scrollHeight) + 'px';
        }
    };

    // ==========================================================
    // API PÚBLICA: getData
    // ==========================================================
    TarefaForm.prototype.getData = function() {
        return {
            titulo:       this.el.titulo     ? this.el.titulo.value.trim()     : '',
            descricao:    this.el.descricao  ? this.el.descricao.value.trim()  : '',
            status:       this.el.status     ? this.el.status.value            : 'pendente',
            prioridade:   this.el.prioridade ? this.el.prioridade.value        : 'media',
            data_inicio:  this.el.dataInicio ? this.el.dataInicio.value        : '',
            data_final:   this.el.dataFinal  ? this.el.dataFinal.value         : '',
            categoria_id: this.el.categoria  ? this.el.categoria.value         : '',
        };
    };

    // ==========================================================
    // API PÚBLICA: reset
    // ==========================================================
    TarefaForm.prototype.reset = function() {
        this.form.reset();

        if (this.el.titulo)     this.el.titulo.value     = '';
        if (this.el.descricao)  this.el.descricao.value  = '';
        if (this.el.status)     this.el.status.value     = 'pendente';
        if (this.el.prioridade) this.el.prioridade.value = 'media';
        if (this.el.dataInicio) this.el.dataInicio.value = '';
        if (this.el.dataFinal)  this.el.dataFinal.value  = '';
        if (this.el.categoria)  this.el.categoria.value  = '';

        if (this.el.descricao) {
            this.el.descricao.style.height = 'auto';
        }
    };

    // ==========================================================
    // API PÚBLICA: submit (SEMPRE JSON)
    // ==========================================================
    TarefaForm.prototype.submit = function(url) {
        var self = this;
        var data = this.getData();

        // ==========================================================
        // VALIDAÇÕES CLIENT-SIDE (AJAX, sem required HTML)
        // ==========================================================
        if (!data.titulo) {
            if (window.Notificacao) window.Notificacao.aviso('Título é obrigatório.');
            return Promise.reject(new Error('titulo vazio'));
        }
        if (data.titulo.length > 200) {
            if (window.Notificacao) window.Notificacao.aviso('Título não pode passar de 200 caracteres.');
            return Promise.reject(new Error('titulo longo'));
        }

        if (!data.descricao) {
            if (window.Notificacao) window.Notificacao.aviso('Descrição é obrigatória.');
            return Promise.reject(new Error('descricao vazia'));
        }

        if (!data.data_inicio) {
            if (window.Notificacao) window.Notificacao.aviso('Data de início é obrigatória.');
            return Promise.reject(new Error('data_inicio vazia'));
        }

        // ==========================================================
        // ENVIO
        // ==========================================================
        var headers = {
            'X-Requested-With': 'XMLHttpRequest',
            'Content-Type': 'application/json'
        };

        return fetch(url, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify(data)
        })
        .then(function(r) { return r.json().then(function(j) { return { ok: r.ok, data: j }; }); })
        .then(function(res) {
            if (!res.ok || res.data.success === false) {
                var msg;
                if (res.data.errors && res.data.errors.length > 0) {
                    msg = res.data.errors[0].mensagem;
                } else {
                    msg = res.data.error || res.data.message || 'Erro ao salvar.';
                }
                if (self.onSubmitError) self.onSubmitError(msg);
                else if (window.Notificacao) window.Notificacao.erro(msg);
                throw new Error(msg);
            }

            if (self.onSubmitSuccess) self.onSubmitSuccess(res.data);
            return res.data;
        });
    };

    // ==========================================================
    // Exposição global
    // ==========================================================
    window.TarefaForm = TarefaForm;

    console.log('✅ TarefaForm carregado!');
})();

// ==== totalizadores.js ====
// static/js/modules/pasta_tarefas/components/totalizadores.js
// ==========================================================
// Atualiza os contadores do footer após HTMX trocar a tabela
// ==========================================================

(function() {
    'use strict';

    function recalcularContadoresTarefas() {
        var tbody = document.querySelector('#tbody-tarefas');
        if (!tbody) return;

        var linhas = tbody.querySelectorAll('tr');
        var pendentes = 0;
        var andamento = 0;
        var concluidas = 0;

        linhas.forEach(function(tr) {
            // Ignora linha de "vazio"
            if (tr.querySelector('td[colspan]')) return;

            var badges = tr.querySelectorAll('.badge-pure');
            var statusTxt = '';

            badges.forEach(function(b) {
                var t = b.textContent.trim();
                if (t.indexOf('Concluída') !== -1) statusTxt = 'concluido';
                else if (t.indexOf('Andamento') !== -1) statusTxt = 'em andamento';
                else if (t.indexOf('Pendente') !== -1) statusTxt = 'pendente';
            });

            if (statusTxt === 'concluido')    concluidas++;
            else if (statusTxt === 'em andamento') andamento++;
            else if (statusTxt === 'pendente')     pendentes++;
        });

        var elP = document.getElementById('totalPendentes');
        var elA = document.getElementById('totalAndamento');
        var elC = document.getElementById('totalConcluidas');

        if (elP) elP.textContent = pendentes;
        if (elA) elA.textContent = andamento;
        if (elC) elC.textContent = concluidas;
    }

    // 🔥 HTMX troca a tabela → recalcula
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        var target = evt.detail && evt.detail.target;
        if (!target) return;

        if (target.id === 'tabela-container' ||
            target.id === 'tbody-tarefas' ||
            target.closest('#tabela-container')) {
            recalcularContadoresTarefas();
        }
    });

    console.log('✅ Totalizadores Tarefas carregados!');
})();

// ==== botoes_filtros.js ====
// static/js/modules/pasta_tarefas/components/botoes_filtros.js
// ==========================================================
// Atualiza o visual dos botões de filtro (Ativas/Inativas/Todas)
// após HTMX trocar a tabela
// ==========================================================

(function() {
    'use strict';

    function atualizarBotoesTarefas() {
        var input = document.getElementById('mostrar_inativas_input');
        if (!input) return;

        var valor = input.value;
        if (!valor) return;

        document.querySelectorAll('#botoes-transacao .btn-filter').forEach(function(btn) {
            btn.classList.remove('btn-active-toggle');
        });

        var botaoAtivo = document.querySelector(
            '#botoes-transacao button[hx-vals*=\'mostrar_inativas": "' + valor + '"\']'
        );
        if (botaoAtivo) botaoAtivo.classList.add('btn-active-toggle');
    }

    // HTMX troca a tabela → atualiza botões
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        var target = evt.detail && evt.detail.target;
        if (!target) return;

        if (target.id === 'tabela-container' ||
            target.id === 'mostrar_inativas_input' ||
            target.closest('#tabela-container')) {
            atualizarBotoesTarefas();
        }
    });

    console.log('✅ Botoes filtros Tarefas carregado!');
})();

// ==== ordenacao.js ====
// static/js/modules/pasta_tarefas/components/ordenacao.js
// ==========================================================
// ORDENAÇÃO DE COLUNAS — TAREFAS (2099)
// Event delegation — funciona sempre, sem listeners duplicados
// ==========================================================

(function() {
    'use strict';

    let colunaAtual = null;
    let ordemAtual = 'asc';

    // Tipos por índice de coluna (Tarefas)
    const TIPOS_COLUNAS = {
        0: 'numero',   // Nº REG.
        1: 'texto',    // TÍTULO
        2: 'texto',    // STATUS
        3: 'data',     // DATA INICIO
        4: 'data',     // DATA FINAL
        5: 'data',     // DATA FINALIZAÇÃO
        6: 'texto',    // CATEGORIA
        7: 'texto',    // PRIORIDADE
    };

    // ==========================================================
    // EXTRAI VALOR PRA COMPARAÇÃO
    // ==========================================================
    function getValorParaComparacao(celula, tipo) {
        const texto = celula?.innerText?.trim() || '';

        if (tipo === 'numero') {
            return parseFloat(texto.replace(/\D/g, '')) || 0;
        }
        if (tipo === 'data') {
            if (texto && texto !== '-') {
                const partes = texto.split('/');
                if (partes.length === 3) {
                    return new Date(partes[2], partes[1] - 1, partes[0]).getTime();
                }
            }
            return 0;
        }
        return (texto || '').toLowerCase();
    }

    // ==========================================================
    // ORDENA
    // ==========================================================
    function ordenarTabela(colunaIndex, tipo) {
        const tbody = document.querySelector('.custom-table tbody');
        if (!tbody) return;

        const linhas = Array.from(tbody.querySelectorAll('tr'));
        const linhasValidas = linhas.filter(row => !row.querySelector('td[colspan]'));
        const linhasMensagem = linhas.filter(row => row.querySelector('td[colspan]'));

        const linhasComValor = linhasValidas.map(linha => ({
            linha: linha,
            valor: getValorParaComparacao(linha.children[colunaIndex], tipo)
        }));

        linhasComValor.sort((a, b) => {
            if (a.valor < b.valor) return ordemAtual === 'asc' ? -1 : 1;
            if (a.valor > b.valor) return ordemAtual === 'asc' ? 1 : -1;
            return 0;
        });

        const fragment = document.createDocumentFragment();
        linhasComValor.forEach(item => fragment.appendChild(item.linha));
        linhasMensagem.forEach(row => fragment.appendChild(row));

        tbody.innerHTML = '';
        tbody.appendChild(fragment);
    }

    // ==========================================================
    // EVENT DELEGATION — 1 listener só
    // ==========================================================
    document.addEventListener('click', function(e) {
        const th = e.target.closest('.custom-table th');
        if (!th) return;

        // Descobre o índice
        const ths = Array.from(th.parentNode.children);
        const idx = ths.indexOf(th);

        const tipo = TIPOS_COLUNAS[idx];
        if (!tipo) return;   // coluna "AÇÕES" (última) não ordena

        // Remove classes de todos
        document.querySelectorAll('.custom-table th').forEach(h => {
            h.classList.remove('asc', 'desc');
        });

        // Alterna ordem
        if (colunaAtual === idx) {
            ordemAtual = ordemAtual === 'asc' ? 'desc' : 'asc';
        } else {
            colunaAtual = idx;
            ordemAtual = 'asc';
        }

        th.classList.add(ordemAtual === 'asc' ? 'asc' : 'desc');
        ordenarTabela(idx, tipo);
    });

    // ==========================================================
    // MARCA COLUNAS ORDENÁVEIS
    // ==========================================================
    function marcarColunasOrdenaveis() {
        const ths = document.querySelectorAll('.custom-table th');
        ths.forEach((th, idx) => {
            if (TIPOS_COLUNAS[idx]) th.classList.add('sortable');
        });
    }

    // Ao carregar
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', marcarColunasOrdenaveis);
    } else {
        marcarColunasOrdenaveis();
    }

    // Após HTMX trocar a tabela
    document.addEventListener('htmx:afterSwap', function(evento) {
        if (evento.detail.target?.id === 'tabela-container') {
            marcarColunasOrdenaveis();
        }
    });

    console.log('✅ Ordenação Tarefas (2099) carregada!');

})();

// ==== tarefa-nova.js ====
// static/js/modules/pasta_tarefas/modals/tarefa-nova.js
// ==========================================================
// MODAL NOVA TAREFA - HTMX injeta, JS inicializa
// ==========================================================

(function() {
    'use strict';

    var formInstance = null;

    function instanciar() {
        var formEl = document.getElementById('formNovaTarefa');
        if (!formEl) return null;
        if (formInstance && formInstance.form === formEl) return formInstance;

        formInstance = new window.TarefaForm(formEl, {
            mode: 'create',
            onSubmitSuccess: function(result) {
                if (window.Notificacao) window.Notificacao.sucesso(result.message || 'Tarefa salva!');
                fecharModalNovaTarefa();

                // Recarrega tabela via HTMX
                if (window.recarregarTabelaTarefas) {
                    window.recarregarTabelaTarefas();
                } else if (window.htmx) {
                    htmx.ajax('GET', '/tarefas', { target: '#tabela-container', swap: 'outerHTML' });
                }
            }
        });
        return formInstance;
    }

    function fecharModalNovaTarefa() {
        var container = document.getElementById('modal-nova-container');
        if (container) container.innerHTML = '';
        document.body.style.overflow = '';
        formInstance = null;
    }

    function salvarNovaTarefa() {
        var f = instanciar();
        if (!f) return;

        var btn = document.querySelector('#footerFixoNova .btn-footer-primary');
        if (btn) {
            btn.disabled = true;
            btn.dataset.txt = btn.innerHTML;
            btn.innerHTML = 'Salvando...';
        }

        f.submit('/tarefas/nova_tarefa/salvar')
         .catch(function() { /* já notificado */ })
         .finally(function() {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = btn.dataset.txt || 'SALVAR';
            }
         });
    }

    // ==========================================================
    // HTMX injeta o modal → inicializa o form
    // ==========================================================
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        var target = evt.detail && evt.detail.target;
        if (!target) return;
        if (target.id !== 'modal-nova-container') return;

        var formEl = document.getElementById('formNovaTarefa');
        if (!formEl) return;

        // Foca no título
        setTimeout(function() {
            var titulo = formEl.querySelector('.js-titulo');
            if (titulo) titulo.focus();
        }, 100);

        // Instancia o form
        instanciar();
        document.body.style.overflow = 'hidden';

        console.log('🔁 HTMX injetou modal NOVA TAREFA');
    });

    // Escape fecha
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var modal = document.getElementById('modalNovaTarefa');
            if (modal && modal.offsetParent !== null) fecharModalNovaTarefa();
        }
    });

    // Clique fora fecha
    document.addEventListener('click', function(e) {
        var modal = document.getElementById('modalNovaTarefa');
        if (modal && e.target === modal) fecharModalNovaTarefa();
    });

    // Exposição global
    window.fecharModalNovaTarefa = fecharModalNovaTarefa;
    window.salvarNovaTarefa = salvarNovaTarefa;

    console.log('✅ MODAL NOVA TAREFA carregado!');
})();

// ==== tarefa-editar.js ====
// static/js/modules/pasta_tarefas/modals/tarefa-editar.js
// ==========================================================
// MODAL EDITAR TAREFA - HTMX injeta, JS popula via /dados/
// ==========================================================

(function() {
    'use strict';

    var sequenciaAtual = null;
    var formInstance = null;

    function instanciar(formEl) {
        if (!formEl) return null;
        if (formInstance && formInstance.form === formEl) return formInstance;

        formInstance = new window.TarefaForm(formEl, {
            mode: 'edit',
            onSubmitSuccess: function(result) {
                if (window.Notificacao) window.Notificacao.sucesso(result.message || 'Tarefa atualizada!');
                fecharModalEditarTarefa();

                if (window.recarregarTabelaTarefas) {
                    window.recarregarTabelaTarefas();
                } else if (window.htmx) {
                    htmx.ajax('GET', '/tarefas', { target: '#tabela-container', swap: 'outerHTML' });
                }
            }
        });
        return formInstance;
    }

    function abrirModalEditarTarefa(seq) {
        sequenciaAtual = seq;

        var modal = document.getElementById('modalEditarTarefa');
        var formEl = document.getElementById('formEditarTarefa');
        if (!modal || !formEl) return;

        if (!sequenciaAtual) {
            if (window.Notificacao) window.Notificacao.erro('Sequência da tarefa não identificada.');
            return;
        }

        modal.classList.add('active');
        modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';

        // Spinner
        var body = modal.querySelector('.fin-modal-body');
        var loading = null;
        if (body) {
            loading = document.createElement('div');
            loading.id = 'editLoadingOverlay';
            loading.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);display:flex;justify-content:center;align-items:center;flex-direction:column;z-index:10;border-radius:8px;';
            loading.innerHTML = '<div style="width:40px;height:40px;border:4px solid #fff;border-top-color:#2563eb;border-radius:50%;animation:spin 0.8s linear infinite;"></div><p style="color:#fff;margin-top:10px;">Carregando dados...</p>';
            body.style.position = 'relative';
            body.appendChild(loading);
        }

        fetch('/tarefas/edit_tarefas/dados/' + sequenciaAtual, {
            method: 'GET',
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(function(r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function(resposta) {
            if (loading) loading.remove();
            var data = resposta.data || resposta;

            // Atualiza título do modal
            var tituloEl = modal.querySelector('#finEditarSequencia');
            if (tituloEl && data.sequencia) {
                tituloEl.textContent = 'Editar Tarefa #' + data.sequencia;
            }
            if (formEl && data.sequencia) {
                formEl.dataset.tarefaSequencia = data.sequencia;
            }

            var f = instanciar(formEl);
            if (f) f.setData(data);
        })
        .catch(function(error) {
            console.error('❌ Erro no GET dados:', error);
            if (loading) loading.remove();
            if (body) body.innerHTML = '<div style="color:#ef4444;padding:20px;">Erro ao carregar dados</div>';
        });
    }

    function fecharModalEditarTarefa() {
        var container = document.getElementById('modal-editar-container');
        if (container) container.innerHTML = '';
        document.body.style.overflow = '';
        formInstance = null;
        sequenciaAtual = null;
    }

    function salvarEditarTarefa() {
        var formEl = document.getElementById('formEditarTarefa');
        sequenciaAtual = (formEl && formEl.dataset.tarefaSequencia) || sequenciaAtual;

        if (!sequenciaAtual || sequenciaAtual === 'None') {
            if (window.Notificacao) window.Notificacao.erro('Sequência da tarefa não identificada.');
            return;
        }

        var f = instanciar(formEl);
        if (!f) return;

        var btn = document.querySelector('#footerFixoEditar .btn-footer-primary');
        if (btn) {
            btn.disabled = true;
            btn.dataset.txt = btn.innerHTML;
            btn.innerHTML = 'Salvando...';
        }

        f.submit('/tarefas/edit_tarefas/' + sequenciaAtual)
         .catch(function() { /* já notificado */ })
         .finally(function() {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = btn.dataset.txt || 'ATUALIZAR';
            }
         });
    }

    // ==========================================================
    // HTMX injeta o modal → popula
    // ==========================================================
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        var target = evt.detail && evt.detail.target;
        if (!target) return;
        if (target.id !== 'modal-editar-container') return;

        var formEl = document.getElementById('formEditarTarefa');
        if (!formEl) return;

        var seq = formEl.dataset.tarefaSequencia;
        if (!seq || seq === 'None') {
            console.warn('⚠️ HTMX injetou modal de editar sem data-tarefa-sequencia');
            return;
        }

        console.log('🔁 HTMX injetou modal EDITAR TAREFA, populando via /dados/' + seq);
        abrirModalEditarTarefa(seq);
    });

    // Escape / clique fora
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var modal = document.getElementById('modalEditarTarefa');
            if (modal && modal.offsetParent !== null) fecharModalEditarTarefa();
        }
    });

    document.addEventListener('click', function(e) {
        var modal = document.getElementById('modalEditarTarefa');
        if (modal && e.target === modal) fecharModalEditarTarefa();
    });

    // Exposição global
    window.abrirModalEditarTarefa = abrirModalEditarTarefa;
    window.fecharModalEditarTarefa = fecharModalEditarTarefa;
    window.salvarEditarTarefa = salvarEditarTarefa;

    console.log('✅ MODAL EDITAR TAREFA carregado!');
})();

// ==== excluir_tarefa.js ====
// static/js/modules/pasta_tarefas/acoes_e_modais/pasta_excluir/excluir_tarefa.js
// ==========================================================
// EXCLUIR (inativar) — HTMX puro
// ==========================================================

(function() {
    'use strict';

    let modalAberto = false;

    // ==========================================================
    // Abrir o modal
    // ==========================================================
    window.abrirModalExcluirTarefa = function(config) {
        if (modalAberto) return;

        const modal = document.getElementById('modalConfirmacao');
        const titulo = document.getElementById('modalTitulo');
        const texto = document.getElementById('modalTexto');

        // 🔥 Clona botão pra limpar listeners HTMX antigos
        let btnConfirmar = document.getElementById('btnConfirmarExcluirTarefa');
        if (btnConfirmar && btnConfirmar.parentNode) {
            const clone = btnConfirmar.cloneNode(true);
            btnConfirmar.parentNode.replaceChild(clone, btnConfirmar);
            btnConfirmar = clone;
        }

        const btnCancelar = document.getElementById('btnCancelarExcluirTarefa');

        if (!modal || !btnConfirmar || !btnCancelar) {
            console.error('❌ Modal de exclusão não encontrado');
            return;
        }

        modalAberto = true;
        if (titulo) titulo.textContent = config.titulo;
        if (texto) texto.textContent = config.texto;
        modal.classList.add('active');

        // Configura hx-post dinamicamente
        btnConfirmar.setAttribute('hx-post', config.url);
        btnConfirmar.setAttribute('hx-target', '#tbody-tarefas');
        btnConfirmar.setAttribute('hx-swap', 'outerHTML');

        if (window.htmx) window.htmx.process(btnConfirmar);

        const fecharModal = () => {
            modal.classList.remove('active');
            modalAberto = false;
        };

        btnCancelar.onclick = fecharModal;
        modal.onclick = function(e) {
            if (e.target === modal) fecharModal();
        };

        // Fecha se sucesso
        btnConfirmar.addEventListener('htmx:afterRequest', function onDone(evt) {
            const status = evt.detail.xhr.status;
            if (status >= 200 && status < 300) {
                fecharModal();
            }
            btnConfirmar.removeEventListener('htmx:afterRequest', onDone);
        });
    };

    // ==========================================================
    // Delegação: clique no botão Excluir da linha
    // ==========================================================
    document.addEventListener('click', function(e) {
        const btn = e.target.closest('.btn-excluir');
        if (!btn) return;

        e.preventDefault();

        // 🔥 Zera o estado (garante que a 2ª vez funcione)
        modalAberto = false;

        const seq = btn.dataset.sequencia;
        const titulo = btn.dataset.titulo;

        window.abrirModalExcluirTarefa({
            titulo: 'Inativar Tarefa',
            texto: 'Deseja inativar a tarefa: "' + titulo + '"?',
            url: '/tarefas/excluir_tarefa/' + seq
        });
    });

    // ==========================================================
    // Toast via HX-Trigger
    // ==========================================================
    document.body.addEventListener('tarefaInativada', function() {
        modalAberto = false;
        const modal = document.getElementById('modalConfirmacao');
        if (modal) modal.classList.remove('active');

        if (window.Notificacao) window.Notificacao.sucesso('Tarefa inativada com sucesso!');
    });

    console.log('✅ Sistema de exclusão Tarefas (HTMX) carregado!');
})();

// ==== concluir_tarefa.js ====
// static/js/modules/pasta_tarefas/acoes_e_modais/pasta_concluir/concluir_tarefa.js
// ==========================================================
// CONCLUIR — HTMX puro (com motivo)
// ==========================================================

(function() {
    'use strict';

    let modalAberto = false;

    // ==========================================================
    // Abrir o modal
    // ==========================================================
    window.abrirModalConcluirTarefa = function(config) {
        if (modalAberto) return;

        const modal = document.getElementById('modalConcluirTarefa');
        const tituloEl = document.getElementById('concluirTitulo');
        const motivoEl = document.getElementById('motivoConclusao');

        // 🔥 Clona botão pra limpar listeners HTMX antigos
        let btnConfirmar = document.getElementById('btnConfirmarConcluirTarefa');
        if (btnConfirmar && btnConfirmar.parentNode) {
            const clone = btnConfirmar.cloneNode(true);
            btnConfirmar.parentNode.replaceChild(clone, btnConfirmar);
            btnConfirmar = clone;
        }

        const btnCancelar = document.getElementById('btnCancelarConcluirTarefa');

        if (!modal || !btnConfirmar || !btnCancelar) {
            console.error('❌ Modal de conclusão não encontrado');
            return;
        }

        modalAberto = true;
        if (tituloEl) tituloEl.textContent = 'Tarefa: ' + (config.titulo || '');
        if (motivoEl) motivoEl.value = '';
        modal.classList.add('active');

        // Configura hx-post dinamicamente
        btnConfirmar.setAttribute('hx-post', config.url);
        btnConfirmar.setAttribute('hx-target', '#tbody-tarefas');
        btnConfirmar.setAttribute('hx-swap', 'outerHTML');

        // Passa o motivo como parâmetro do POST
        btnConfirmar.setAttribute('hx-include', '#motivoConclusao');

        if (window.htmx) window.htmx.process(btnConfirmar);

        const fecharModal = () => {
            modal.classList.remove('active');
            modalAberto = false;
        };

        btnCancelar.onclick = fecharModal;
        modal.onclick = function(e) {
            if (e.target === modal) fecharModal();
        };

        // Fecha se sucesso
        btnConfirmar.addEventListener('htmx:afterRequest', function onDone(evt) {
            const status = evt.detail.xhr.status;
            if (status >= 200 && status < 300) {
                fecharModal();
            }
            btnConfirmar.removeEventListener('htmx:afterRequest', onDone);
        });
    };

    // ==========================================================
    // Delegação: clique no botão Concluir da linha
    // ==========================================================
    document.addEventListener('click', function(e) {
        const btn = e.target.closest('.btn-concluir');
        if (!btn) return;

        e.preventDefault();

        modalAberto = false;

        const seq = btn.dataset.sequencia;
        const titulo = btn.dataset.titulo;

        window.abrirModalConcluirTarefa({
            titulo: titulo,
            url: '/tarefas/concluir_tarefa/' + seq
        });
    });

    // ==========================================================
    // Toast via HX-Trigger
    // ==========================================================
    document.body.addEventListener('tarefaConcluida', function() {
        modalAberto = false;
        const modal = document.getElementById('modalConcluirTarefa');
        if (modal) modal.classList.remove('active');

        if (window.Notificacao) window.Notificacao.sucesso('Tarefa concluída com sucesso!');
    });

    console.log('✅ Sistema de conclusão Tarefas (HTMX) carregado!');
})();

// ==== detalhes_tarefa.js ====
// static/js/modules/pasta_tarefas/acoes_e_modais/pasta_detalhes/detalhes_tarefa.js
// ==========================================================
// DETALHES DA TAREFA — fetch JSON → modal
// ==========================================================

(function() {
    'use strict';

    // ==========================================================
    // Ver detalhes
    // ==========================================================
    window.verDetalhesTarefa = function(seq) {
        fetch('/tarefas/detalhes/' + seq, {
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            const modal = document.getElementById('modalDetalhesTarefa');
            const conteudo = document.getElementById('conteudoDetalhes');
            if (!modal || !conteudo) return;

            // 🔥 Layout igual Finanças: grid + fields com labels
            conteudo.innerHTML =
                '<div class="modal-detalhes-grid">' +

                    '<div class="modal-detalhes-field full-width">' +
                        '<div class="field-detalhes-label">📝 Título</div>' +
                        '<div class="field-detalhes-value">' + (data.titulo || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field full-width">' +
                        '<div class="field-detalhes-label">📄 Descrição</div>' +
                        '<div class="field-detalhes-value field-detalhes-value-scroll">' + (data.descricao || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">📊 Status</div>' +
                        '<div class="field-detalhes-value">' + (data.status_label || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">🎯 Prioridade</div>' +
                        '<div class="field-detalhes-value">' + (data.prioridade_label || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">🏷️ Categoria</div>' +
                        '<div class="field-detalhes-value">' + (data.categoria || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">📅 Início</div>' +
                        '<div class="field-detalhes-value">' + (data.data_inicio || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">⏰ Prazo</div>' +
                        '<div class="field-detalhes-value">' + (data.data_final || '-') + '</div>' +
                    '</div>' +

                    '<div class="modal-detalhes-field">' +
                        '<div class="field-detalhes-label">✅ Finalizada em</div>' +
                        '<div class="field-detalhes-value">' + (data.data_finalizacao || '-') + '</div>' +
                    '</div>' +

                    (data.motivo_conclusao ?
                        '<div class="modal-detalhes-field full-width">' +
                            '<div class="field-detalhes-label">💬 Motivo da conclusão</div>' +
                            '<div class="field-detalhes-value field-detalhes-value-scroll">' + data.motivo_conclusao + '</div>' +
                        '</div>'
                        : '') +

                '</div>';

            modal.classList.add('active');
        })
        .catch(function(err) {
            console.error(err);
            if (window.Notificacao) window.Notificacao.erro('Erro ao buscar detalhes.');
        });
    };

    // ==========================================================
    // Fechar modal
    // ==========================================================
    window.fecharModalDetalhes = function(event) {
        if (event && event.target) {
            const modal = document.getElementById('modalDetalhesTarefa');
            if (modal && event.target !== modal) return;
        }
        const modal = document.getElementById('modalDetalhesTarefa');
        if (modal) modal.classList.remove('active');
    };

    console.log('✅ Sistema de detalhes Tarefas (JSON) carregado!');
})();

